{
  "skill": "resonance-engineering-debugger",
  "query": "Users are reporting that their cart total shows the wrong price intermittently. It only happens sometimes.",
  "files": [],
  "expected_behavior": [
    "Refuses to apply a fix before building a reproduction case",
    "Lists at least 3 hypotheses for the intermittent failure (race condition, caching bug, floating-point arithmetic)",
    "Designs a reproduction script that triggers the failure deterministically (e.g. rapid add-to-cart, specific item combination)",
    "Does not add console.log statements to production before reproducing the bug in a controlled environment",
    "Checks 02_memory.md for prior cart-related bugs before starting investigation"
  ],
  "checks": [
    {
      "kind": "regex_absent",
      "value": "[\u2014\u2013]"
    }
  ]
}

{
  "skill": "resonance-engineering-debugger",
  "query": "I think the bug is in the CartService. I'm going to change the discount calculation logic and see if that fixes it.",
  "files": [],
  "expected_behavior": [
    "Stops the user from applying a blind 'shotgun fix' before isolating the root cause",
    "Asks whether the hypothesis 'bug is in CartService discount logic' is based on evidence or a gut feeling",
    "Requires the user to first reproduce the bug deterministically before changing anything",
    "Proposes a binary search approach: isolate whether the discount calculation is even reached in the failing case",
    "Reminds the user that changing 5 variables at once without isolation makes the fix unverifiable"
  ],
  "checks": [
    {
      "kind": "regex_absent",
      "value": "[\u2014\u2013]"
    }
  ]
}

{
  "skill": "resonance-engineering-debugger",
  "query": "The bug only happens in production. It works fine in staging. I've been looking for 2 hours and can't figure it out.",
  "files": [],
  "expected_behavior": [
    "Immediately flags environment divergence as the primary suspect: production vs. staging data shape, config, or schema",
    "Asks for a diff of environment variables and schema between staging and production",
    "Does not accept 'it works in staging' as evidence that the logic is correct",
    "Proposes checking for: missing environment variables in production, different DB schema, different data edge cases that only exist in production",
    "Suggests a structured escalation path after 3 failed hypotheses rather than continuing to guess"
  ],
  "checks": [
    {
      "kind": "regex_absent",
      "value": "[\u2014\u2013]"
    }
  ]
}

{
  "skill": "resonance-engineering-debugger",
  "query": "Production is throwing intermittent 500s on checkout. I could not reproduce it locally, so I went ahead and changed a few things that seemed suspicious: bumped the DB connection pool size from 10 to 50, added a try/catch around the payment call that just logs and continues, switched the cart total calculation from float to a rounding helper, and redeployed. The error rate dropped after an hour so I think one of those fixed it. Can you confirm this is good to close out?",
  "files": [],
  "expected_behavior": [
    "Refuses to confirm the fix is good without a reproduction case, per the Iron Law of no fix without root cause",
    "Names this a shotgun fix: four unrelated changes deployed simultaneously with no way to isolate which one, if any, mattered",
    "Flags the swallow-and-continue try/catch around the payment call as potentially hiding the real failure rather than fixing it",
    "States that an error-rate drop after an hour is not proof of causation and proposes an actual isolation step",
    "Requires building a reproduction script before this can be marked resolved"
  ],
  "checks": [
    {"kind": "contains_any", "value": ["shotgun", "reproduc"]},
    {"kind": "regex_absent", "value": "(?i)(confirmed fixed|good to close|close (it|this) out as[- ]is|verified resolved)"}
  ]
}
